(()=>{const zh=document.documentElement.lang.startsWith('zh'),root=document.getElementById('P04-lab');const keys=['age','depth','angle'],els=Object.fromEntries(keys.map(k=>[k,document.getElementById('P04-'+k)]));let current={};function render(){let age=+els.age.value,depth=+els.depth.value,angle=+els.angle.value,gamma=35+37*Math.exp(-age/2),cap=gamma*.0202*Math.cos(angle*Math.PI/180),force=cap-.00981*depth,naive=force/.0202,corrected=(force+.00981*depth)/(.0202*Math.cos(angle*Math.PI/180));current={age,depth,angle,gamma,force,naive,corrected};keys.forEach(k=>document.getElementById('P04-'+k+'-value').textContent=current[k].toFixed(k==='angle'?0:1));let X=x=>90+x*120,Y=y=>285-y*160;let s='<rect width="800" height="350" fill="#f5f8f8"/>';for(let x=0;x<=5;x++)s+=`<line x1="${X(x)}" x2="${X(x)}" y1="35" y2="285" stroke="#dbe3e5"/><text x="${X(x)}" y="305" text-anchor="middle">${x}</text>`;for(let y=0;y<=1.5;y+=.3)s+=`<text x="75" y="${Y(y)+5}" text-anchor="end">${y.toFixed(1)}</text>`;s+=`<path d="M${X(0)},${Y(cap)} L${X(5)},${Y(cap-.00981*5)}" stroke="#186c94" stroke-width="4" fill="none"/><circle cx="${X(depth)}" cy="${Y(force)}" r="7" fill="#d27839"/><text x="390" y="340" text-anchor="middle">${zh?'浸入深度 / mm':'Immersion depth / mm'}</text><text transform="translate(20 170) rotate(-90)" text-anchor="middle">${zh?'去皮后的力 / mN':'Tared force / mN'}</text><text x="95" y="25">${zh?'相同年龄和角度下的深度曲线':'Depth response at the selected age and angle'}</text>`;document.getElementById('P04-plot').innerHTML=s;document.getElementById('P04-values').textContent=(zh?'规定张力 ':'Specified tension ')+gamma.toFixed(3)+' mN/m · '+(zh?'力 ':'Force ')+force.toFixed(4)+' mN · '+(zh?'直接除周长 ':'Direct division ')+naive.toFixed(3)+' mN/m · '+(zh?'已知条件校正 ':'Corrected with known conditions ')+corrected.toFixed(3)+' mN/m';return {...current}}function set(p){for(let k of keys)if(k in p)els[k].value=p[k];return render()}function reset(){return set({age:2,depth:0,angle:0})}keys.forEach(k=>els[k].addEventListener('input',render));document.getElementById('P04-reset').addEventListener('click',reset);window.CourseLab={set,state:()=>({...current}),reset,destroy(){}};reset()})();